/*
 * A375119  Begin A060403 with n instead of 1; a(n) is the position in the new
 *          sequence at which it generates the same numbers as A060403 or
 *          a(n)=0 if it doesn't.
 * https://oeis.org/A375119
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the position in the sequence starting with n * where it
 *            first produces a term that also appears in the sequence *
 *            generated by * a(1)=1, a(k+1)=a(k)+len(word(a(k))) , * where
 *            len(word(x)) is the number of letters in the English word * for
 *            x (spaces and hyphens ignored). If no such term oc...
 * Range:     u8 n <= 46, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

extern seq_t a(idx_t n);

/* ---------- internal helpers ---------- */

/* Lengths of English words for 1–19 and 20,30,…,90 (no spaces or hyphens) */
static const int unit_len[20] = {
    0,   /* 0 unused */
    3,   /* one   */
    3,   /* two   */
    5,   /* three */
    4,   /* four  */
    4,   /* five  */
    3,   /* six   */
    5,   /* seven */
    5,   /* eight */
    4,   /* nine  */
    3,   /* ten   */
    6,   /* eleven */
    6,   /* twelve */
    8,   /* thirteen */
    8,   /* fourteen */
    7,   /* fifteen */
    7,   /* sixteen */
    9,   /* seventeen */
    8,   /* eighteen */
    8    /* nineteen */
};

/* Lengths of tens (20,30,…,90); index 0 and 1 unused. */
static const int tens_len[10] = {
    0, 0, 6, 6, 5, 5, 5, 7, 6, 6
};

/* Magnitude lengths: thousands, millions, billions, etc.  Index 0 unused. */
static const int mag_len[11] = {
    0, /* 0 */
    8, /* thousand  */
    7, /* million   */
    7, /* billion   */
    8, /* trillion  */
   10, /* quadrillion */
   10, /* quintillion */
    9, /* sextillion */
   10, /* septillion */
    9, /* octillion */
   10  /* nonillion   */
};

/* Compute word length of a number < 1000 */
static unsigned int part_len_low3(uint64_t n) {
    if (n == 0) return 0;
    unsigned int len = 0;
    if (n >= 100) {
        unsigned int h = n / 100;
        len += unit_len[h] + 7;            /* "hundred" */
        n %= 100;
        if (n == 0) return len;
    }
    if (n >= 20) {
        unsigned int t = n / 10;
        len += tens_len[t];
        unsigned int u = n % 10;
        if (u) len += unit_len[u];
    } else {            /* 1..19 */
        len += unit_len[n];
    }
    return len;
}

/* Count letters in the full English name of n (no spaces/hyphens). */
static unsigned int wordlen_uint64(uint64_t n) {
    unsigned int total = 0;
    unsigned int pos = 0;          /* 0: units, 1: thousands, 2: millions ... */
    while (n > 0) {
        unsigned int group = n % 1000;
        if (group) {
            unsigned int len = part_len_low3(group);
            if (pos > 0) len += mag_len[pos];
            total += len;
        }
        n /= 1000;
        ++pos;
    }
    return total;
}

static unsigned int wordlen(seq_t n) { return wordlen_uint64((uint64_t)n); }

/* ----------------- A060403 storage ----------------- */
static seq_t *A = NULL;      /* array of sequence values */
static size_t A_len = 0;      /* number of stored values */
static size_t A_cap = 0;      /* allocated capacity */

/* Grow the array to hold at least need entries */
static void ensure_A_capacity(size_t need) {
    if (need <= A_cap) return;
    size_t new_cap = A_cap ? A_cap << 1 : 128;
    while (new_cap < need) new_cap <<= 1;
    A = (seq_t *)realloc(A, new_cap * sizeof(seq_t));
    A_cap = new_cap;
}

/* Extend A so that its last value is >= max_val (if max_val==A_last it still
 * stores the current last value).  The function assumes A is non‑empty
 * after the first call.
 */
static void build_A_upto(seq_t max_val) {
    if (A_len == 0) {          /* initialise with first term 1 */
        ensure_A_capacity(1);
        A[0] = (seq_t)1;
        A_len = 1;
    }
    while (A_len > 0 && A[A_len-1] <= max_val) {
        seq_t next = A[A_len-1] + (seq_t)wordlen(A[A_len-1]);
        ensure_A_capacity(A_len + 1);
        A[A_len++] = next;
    }
}

/* Binary search: true if val in A[0 .. A_len-1] */
static int in_A(seq_t val) {
    size_t lo = 0, hi = A_len;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        seq_t v = A[mid];
        if (v == val) return 1;
        if (v < val) lo = mid + 1;
        else hi = mid;
    }
    return 0;
}

/* ----------------- public function ----------------- */
seq_t a(idx_t n) {
    seq_t start = (seq_t)n;
    seq_t cur   = start;
    size_t k = 1;                          /* position in new sequence */
    const size_t MAX_ITER = 2000000;       /* safety cap */

    while (1) {
        build_A_upto(cur);
        if (in_A(cur)) return (seq_t)k;
        if (k >= MAX_ITER) return (seq_t)0;   /* assume no match */
        cur = cur + (seq_t)wordlen(cur);
        ++k;
    }
}
